    all:['全部','All','Tous','Todos','Guztiak'],identity:['基因身份','Gene identity','Identité des gènes','Identidad de genes','Gene-identitatea'],annotation:['功能与状态注释','Functional and state annotation','Annotation fonctionnelle et des états','Anotación funcional y de estados','Funtzio- eta egoera-anotazioa'],regulation:['转录调控','Transcriptional regulation','Régulation transcriptionnelle','Regulación transcripcional','Transkripzio-erregulazioa'],interaction:['互作与复合体','Interactions and complexes','Interactions et complexes','Interacciones y complejos','Elkarrekintzak eta konplexuak'],expression:['表达参考','Expression references','Références d’expression','Referencias de expresión','Adierazpen-erreferentziak'],population:['群体与原始数据','Population and raw data','Populations et données brutes','Poblaciones y datos originales','Populazioak eta datu gordinak'],
